def product_by_id(product_id):
    return next((p for p in PRODUCTS if p["id"] == product_id), None)


def public_product(p):
    return {k: v for k, v in p.items() if k not in ("fulfillment", "kind", "color")} | {"price": 0, "currency": "KGS"}
